ALTER TABLE "health_records" ENABLE ROW LEVEL SECURITY;--> statement-breakpoint
CREATE POLICY "health_select" ON "health_records" AS PERMISSIVE FOR SELECT TO public USING (current_setting('app.role', true) = 'admin' OR ("health_records"."owner_id" = current_setting('app.user_id', true) AND current_setting('app.role', true) = 'doctor') OR "health_records"."lookup_hash" = current_setting('app.lookup_hash', true));--> statement-breakpoint
CREATE POLICY "health_insert" ON "health_records" AS PERMISSIVE FOR INSERT TO public WITH CHECK (current_setting('app.role', true) IN ('admin', 'doctor') AND "health_records"."owner_id" = current_setting('app.user_id', true));--> statement-breakpoint
CREATE POLICY "health_update" ON "health_records" AS PERMISSIVE FOR UPDATE TO public USING (current_setting('app.role', true) = 'admin' OR ("health_records"."owner_id" = current_setting('app.user_id', true) AND current_setting('app.role', true) = 'doctor')) WITH CHECK (current_setting('app.role', true) = 'admin' OR ("health_records"."owner_id" = current_setting('app.user_id', true) AND current_setting('app.role', true) = 'doctor'));--> statement-breakpoint
CREATE POLICY "health_delete" ON "health_records" AS PERMISSIVE FOR DELETE TO public USING (current_setting('app.role', true) = 'admin' OR ("health_records"."owner_id" = current_setting('app.user_id', true) AND current_setting('app.role', true) = 'doctor'));